from typing import List

def winding_number(word: List[bool]) -> int:
    """Encode map for pi_1(S^1): net signed winding of a boolean loop word."""
    acc = 0
    for b in word:
        acc = acc + 1 if b else acc - 1
    return acc

def canonical_loop(n: int) -> List[bool]:
    """Decode map: a word whose winding number is exactly n."""
    return [True] * n if n >= 0 else [False] * (-n)

def reverse_loop(w: List[bool]) -> List[bool]:
    return [not b for b in reversed(w)]

if __name__ == "__main__":
    a = [True, True, False, True]
    b = [False, False, True]
    assert winding_number(a + b) == winding_number(a) + winding_number(b)  # additivity
    assert winding_number(reverse_loop(a)) == -winding_number(a)           # inversion
    for n in range(-5, 6):
        assert winding_number(canonical_loop(n)) == n                      # surjectivity
    print("pi_1(S^1) = Z verified: additivity, inversion, surjectivity OK")

from dataclasses import dataclass
from typing import Callable, Dict, List

@dataclass
class FinGroup:
    elems: List[int]
    op: Callable[[int, int], int]

def is_group_iso(G: FinGroup, H: FinGroup, phi: Dict[int, int]) -> bool:
    if sorted(phi.values()) != sorted(H.elems):
        return False
    return all(phi[G.op(a, b)] == H.op(phi[a], phi[b]) for a in G.elems for b in G.elems)

def compose_iso(phi: Dict[int, int], psi: Dict[int, int]) -> Dict[int, int]:
    return {k: psi[v] for k, v in phi.items()}

if __name__ == "__main__":
    G = FinGroup([0,1,2], lambda a,b:(a+b)%3)
    H = FinGroup([10,11,12], lambda a,b:((a-10)+(b-10))%3+10)
    K = FinGroup([100,101,102], lambda a,b:((a-100)+(b-100))%3+100)
    phi = {0:10,1:11,2:12}; psi = {10:100,11:101,12:102}
    assert is_group_iso(G,H,phi) and is_group_iso(H,K,psi)
    assert is_group_iso(G,K, compose_iso(phi,psi))   # transitivity (structure identity)
    print("Structure identity: G~H, H~K => G~K verified")

